四、微控晶片程式(Arduino IDE)內容：如圖４－５所示。 















#include<Servo.h> 
#include <SoftwareSerial.h> 
#include <Wire.h> 
Servo servo; //180 度馬達 
Servo servo360; //360 度馬達 
#define red 2 //紅外線腳位在 2 
int red2 ; 
SoftwareSerial BT(10, 11);//RX, TX //藍芽 
int BTread=0; //藍芽收到的值 
int led=13; //LED 在13 腳 
int la=12; //蜂鳴器在12 腳 
int t1=0; 
int t2=0; 
int mode; 
int x1=100; // 延遲時間1 
int x3=100; 
int bw=4; 
int bw1=3; 

void setup() 
{ 
 Serial.begin(115200); // 開啟 Serial port, 通訊速率為 9600 bps 
 BT.begin(9600); //藍芽鮑率 
 pinMode(led,OUTPUT); 
 pinMode(la,OUTPUT); 
 pinMode(bw,INPUT); 
 pinMode(red,INPUT); 
} 
void loop() 
{ 

 delay(x3); 
 red2 = digitalRead(red); 
 bw1 = digitalRead(bw); 
 BTread = BT.read(); 
 if(BTread == 's') //時間到手機會傳a 值 
 { 
 // Serial.print("A"); 
 mode=1; 
 } 
 if(mode==1) //時間到啟動功能 
 { 
 digitalWrite(led,HIGH); //led 警示 
 digitalWrite(la,LOW); //蜂鳴器警示 
 delay(100); 
 if (red2==HIGH) 
 { 
 t1=t1+1; 
 digitalWrite(la,LOW); //警示 
 digitalWrite(led,HIGH); //led 警示 
 if(t1==12) 
 { 
 BT.print("c"); //超過12 秒未取藥 
 Serial.print('N'); 
 digitalWrite(led,LOW); //停止警示 
 digitalWrite(la,HIGH); 
 delay(150); 
 Serial.print('O'); 
 mode=0; 
 } 
 delay(900); 
 } 
else 
 { 
 delay(500); 
 t2=t2+1; //手停滯3 秒 
 digitalWrite(la,LOW); //警示 
 digitalWrite(led,HIGH); //led 警示 
 if (t2 == 3) //手停滯3 秒 

