void servo1() 
{ 
 servo.attach(5); //180 馬達通電 
 delay(50); 
 servo.write(0); //180 馬達歸0 度 
 delay(100); 
 Serial.print('O'); 
 servo.write(90); //180 馬達90 度 藥盒打開 
 digitalWrite(led,LOW); //停止警示 
 digitalWrite(la,HIGH); //停止警示 
 delay(9000); 
 servo.write(0); //180 馬達歸0 度 藥盒關閉 
 delay(500); 
 servo.detach(); //180 馬達斷電 
 delay(5000); 
 servo360.attach(6); //360 馬達通電 
 delay(x1); 
 servo360.write(90); // 轉向180 度_逆時針 
 delay(300); 
 // 直接以脈衝寬度控制 
